schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/ai-overview-presence-tracker.json",
  "title": "AI Overview presence report",
  "type": "object",
  "required": ["query_set_version", "tracked_domain", "included_subdomains", "window_start", "window_end", "weeks_observed", "scrape_config", "queries", "rows", "metrics", "findings", "retrofit_list"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "url": {"type": "string", "pattern": "^https://[^\\s/]+/"},
    "host": {"type": "string", "pattern": "^[a-z0-9.-]+\\.[a-z]{2,}$"},
    "rate": {"type": "number", "minimum": 0, "maximum": 1}
  },
  "properties": {
    "__faion_header__": {"type": ["object", "string"]},
    "query_set_version": {"type": "string", "pattern": "^v[0-9]+$"},
    "tracked_domain": {"$ref": "#/definitions/host"},
    "included_subdomains": {"type": "array", "items": {"$ref": "#/definitions/host"}},
    "window_start": {"$ref": "#/definitions/date"},
    "window_end": {"$ref": "#/definitions/date"},
    "weeks_observed": {"type": "integer", "minimum": 1, "maximum": 8},
    "scrape_config": {
      "type": "object",
      "required": ["adapter", "country", "language", "device", "logged_out", "aio_available_checked"],
      "additionalProperties": false,
      "properties": {
        "adapter": {"type": "string", "minLength": 3},
        "country": {"type": "string", "pattern": "^[A-Z]{2}$"},
        "language": {"type": "string", "pattern": "^[a-z]{2}$"},
        "device": {"type": "string", "enum": ["mobile", "desktop"]},
        "logged_out": {"const": true},
        "aio_available_checked": {"const": true}
      }
    },
    "queries": {
      "type": "array",
      "minItems": 20,
      "items": {
        "type": "object",
        "required": ["query", "target_url"],
        "additionalProperties": false,
        "properties": {"query": {"type": "string", "minLength": 3}, "target_url": {"$ref": "#/definitions/url"}}
      }
    },
    "rows": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["query", "week", "observed_at", "status", "aio_present", "citations", "our_domain_cited", "selected_snippet", "panel_position"],
        "additionalProperties": false,
        "properties": {
          "query": {"type": "string", "minLength": 3},
          "week": {"type": "integer", "minimum": 1, "maximum": 8},
          "observed_at": {"anyOf": [{"$ref": "#/definitions/date"}, {"type": "null"}]},
          "status": {"type": "string", "enum": ["observed", "missing"]},
          "aio_present": {"type": ["boolean", "null"]},
          "citations": {"type": "array", "items": {"$ref": "#/definitions/url"}},
          "our_domain_cited": {"type": ["boolean", "null"]},
          "selected_snippet": {"type": ["string", "null"]},
          "panel_position": {"type": ["integer", "null"], "minimum": 1}
        },
        "allOf": [
          {"if": {"properties": {"status": {"const": "missing"}}},
           "then": {"properties": {"observed_at": {"type": "null"}, "aio_present": {"type": "null"}, "citations": {"maxItems": 0}, "our_domain_cited": {"type": "null"}, "selected_snippet": {"type": "null"}, "panel_position": {"type": "null"}}},
           "else": {"properties": {"observed_at": {"type": "string"}, "aio_present": {"type": "boolean"}, "our_domain_cited": {"type": "boolean"}}}},
          {"if": {"properties": {"status": {"const": "observed"}, "aio_present": {"const": true}}},
           "then": {"properties": {"citations": {"minItems": 1}, "panel_position": {"type": "integer"}, "selected_snippet": {"type": "string"}}}},
          {"if": {"properties": {"status": {"const": "observed"}, "aio_present": {"const": false}}},
           "then": {"properties": {"citations": {"maxItems": 0}, "our_domain_cited": {"const": false}, "panel_position": {"type": "null"}, "selected_snippet": {"type": "null"}}}}
        ]
      }
    },
    "metrics": {
      "type": "array",
      "minItems": 3,
      "allOf": [
        {"contains": {"properties": {"name": {"const": "aio_presence_rate"}, "scope": {"const": "window"}}}},
        {"contains": {"properties": {"name": {"const": "our_citation_rate"}, "scope": {"const": "window"}}}},
        {"contains": {"properties": {"name": {"const": "median_panel_position"}, "scope": {"const": "window"}}}}
      ],
      "items": {
        "type": "object",
        "required": ["name", "scope", "week", "value", "unit", "numerator", "denominator"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "enum": ["aio_presence_rate", "our_citation_rate", "median_panel_position"]},
          "scope": {"type": "string", "enum": ["week", "window"]},
          "week": {"type": ["integer", "null"], "minimum": 1, "maximum": 8},
          "value": {"type": "number", "minimum": 0},
          "unit": {"type": "string", "enum": ["ratio", "count"]},
          "numerator": {"type": ["number", "null"], "minimum": 0},
          "denominator": {"type": "integer", "minimum": 0}
        },
        "allOf": [
          {"if": {"properties": {"name": {"const": "median_panel_position"}}}, "then": {"properties": {"unit": {"const": "count"}}}, "else": {"properties": {"unit": {"const": "ratio"}, "value": {"$ref": "#/definitions/rate"}}}},
          {"if": {"properties": {"scope": {"const": "window"}}}, "then": {"properties": {"week": {"type": "null"}}}, "else": {"properties": {"week": {"type": "integer"}}}}
        ]
      }
    },
    "findings": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["metric", "text", "co_occurrence_only", "causal"],
        "additionalProperties": false,
        "properties": {
          "metric": {"type": "string", "enum": ["aio_presence_rate", "our_citation_rate", "median_panel_position"]},
          "text": {"type": "string", "minLength": 20, "not": {"pattern": "(?i)(cost us|because of|due to|led to|caused|thanks to|resulted in)"}},
          "co_occurrence_only": {"const": true},
          "causal": {"const": false}
        }
      }
    },
    "retrofit_list": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["query", "target_url", "weeks_present", "uncited_last_4_weeks", "impressions", "cited_domains"],
        "additionalProperties": false,
        "properties": {
          "query": {"type": "string", "minLength": 3},
          "target_url": {"$ref": "#/definitions/url"},
          "weeks_present": {"type": "integer", "minimum": 5, "maximum": 8},
          "uncited_last_4_weeks": {"const": true},
          "impressions": {"type": "integer", "minimum": 0},
          "cited_domains": {"type": "array", "minItems": 1, "items": {"$ref": "#/definitions/host"}}
        }
      }
    }
  }
}
